import{_ as e,c as r,o as i,ah as h}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"第五十八卦 兑 兑为泽 兑上兑下","description":"周易 - 第五十八卦 兑 兑为泽 兑上兑下","frontmatter":{"title":"第五十八卦 兑 兑为泽 兑上兑下","description":"周易 - 第五十八卦 兑 兑为泽 兑上兑下"},"headers":[],"relativePath":"zh/classics/zhouyi/059.md","filePath":"zh/classics/zhouyi/059.md"}'),l={name:"zh/classics/zhouyi/059.md"};function t(n,a,s,d,o,c){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="兑" tabindex="-1">兑 <a class="header-anchor" href="#兑" aria-label="Permalink to “兑”">​</a></h1><h2 id="卦辞" tabindex="-1">卦辞 <a class="header-anchor" href="#卦辞" aria-label="Permalink to “卦辞”">​</a></h2><p>亨，利贞。</p><h3 id="彖传" tabindex="-1">彖传 <a class="header-anchor" href="#彖传" aria-label="Permalink to “彖传”">​</a></h3><p>兑，说也。刚中而柔外，说以利贞，是以顺乎天，而应乎人。说以先民，民忘其劳；说以犯难，民忘其死；说之大，民劝矣哉！</p><h3 id="象传" tabindex="-1">象传 <a class="header-anchor" href="#象传" aria-label="Permalink to “象传”">​</a></h3><p>丽泽，兑；君子以朋友讲习。</p><h3 id="初九" tabindex="-1">初九 <a class="header-anchor" href="#初九" aria-label="Permalink to “初九”">​</a></h3><p>和兑，吉。象曰：和兑之吉，行未疑也。</p><h3 id="九二" tabindex="-1">九二 <a class="header-anchor" href="#九二" aria-label="Permalink to “九二”">​</a></h3><p>孚兑，吉，悔亡。象曰：孚兑之吉，信志也。</p><h3 id="六三" tabindex="-1">六三 <a class="header-anchor" href="#六三" aria-label="Permalink to “六三”">​</a></h3><p>来兑，凶。象曰：来兑之凶，位不当也。</p><h3 id="九四" tabindex="-1">九四 <a class="header-anchor" href="#九四" aria-label="Permalink to “九四”">​</a></h3><p>商兑，未宁，介疾有喜。象曰：九四之喜，有庆也。</p><h3 id="九五" tabindex="-1">九五 <a class="header-anchor" href="#九五" aria-label="Permalink to “九五”">​</a></h3><p>孚于剥，有厉。象曰：孚于剥，位正当也。</p><h3 id="上六" tabindex="-1">上六 <a class="header-anchor" href="#上六" aria-label="Permalink to “上六”">​</a></h3><p>引兑。象曰：上六引兑，未光也。</p>',19)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
